import {isLightChoice,changedPlaces,decisionOutcomes,personCondition} from './interaction.js?v=0.9.12';
import {eventDigest,eventSummary,discoveryAssignments,diaryMonths} from './daily-view.js?v=0.9.12';
import {schedules,changedSchedules} from './schedules.js?v=0.9.12';
import {progressState,historyReadIntent} from './view-state.js?v=0.9.12';
import {createEncounter} from './encounter.js?v=0.9.12';
import {EVIDENCE,ASSUMPTIONS,monthlyHazard,SUCCESSION_EVIDENCE} from './evidence.js';
import {decisionMonth,personJoinedMonth,personLeftMonth,clientSinceMonth} from './dates.js?v=0.9.12';
import {previewAutoChoice,orderBudget,availableDecisionOptions,autoCanChoose,autoDecision,evolveCompany,currentLeader,companySnapshot,contactCandidate,registerFamily,requestLeadership,requestStrategy,startLife,continueLife,requestExit,policyOptions,setPolicy,MODEL,prepareTimeline,registerDecision,tickMonth,create,advance,resolve,close,restore,activeTeam,activeClients,staff,costs,receivables,concentration,clientWork,chapter,reflection,problems,requestHelp,cancelHelp,eventContext,storyChapters,reviewRecord,PATTERNS,experiencePatterns,personCapacity} from './model.js?v=0.9.12';
import {Playback,milestone,displayDelay} from './playback.js?v=0.9.12';
import {REAL_START,REAL_MOMENTS,momentAssignments,LOAD_LABELS,loadBucket,teamBucket,continuation} from './insights.js?v=0.9.12';
const app=document.querySelector('#app'),modal=document.querySelector('#modal'),decisionModal=document.querySelector('#decision-modal'),KEY='company-life-save-v3';
let changeCue=null,quickNotice='',dialogState=null;
let config,cohort,s=null,draft,saveError='',brokenRaw='',legacy=false,busy=false,selected=null,forecast=null,progressFrame=null,unread=0,seenRecords=0;
const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const num=v=>Math.round(v).toLocaleString('ja-JP'),money=v=>`${num(v)}万円`,seed=()=>crypto.getRandomValues(new Uint32Array(1))[0];
const period=q=>q===0?'創業の日':`${Math.floor((q-1)/4)+1}年目 ${['3月末','6月末','9月末','12月末'][(q-1)%4]}`;
const PREFS='company-life-preferences-v1';
let prefs={speed:.25,auto:'manual'},readingPast=false,introducing=false,recentDelta={};
try{const saved=JSON.parse(localStorage.getItem(PREFS)||'{}');if([.125,.25,.5,1,2].includes(saved.speed))prefs.speed=saved.speed;if(['manual','safe','all'].includes(saved.auto))prefs.auto=saved.auto;}catch{}
function savePrefs(){try{localStorage.setItem(PREFS,JSON.stringify(prefs));}catch{saveError='速度・おまかせ設定を保存できませんでした。';}}
const clock=new Playback({tick:autoTick,delay:speed=>s?.decisionReceipt?5000:s?.pending?6000:displayDelay(s,speed),onChange:refreshPlayback});clock.speed=prefs.speed;
let autoCacheState,autoCacheMode,autoCacheValue;
function autoReady(){if(autoCacheState!==s||autoCacheMode!==prefs.auto){autoCacheState=s;autoCacheMode=prefs.auto;autoCacheValue=autoCanChoose(s,prefs.auto)&&!s.pending.initiated;}return autoCacheValue;}
const speedLabel=value=>`${value/.25}×`,speedValues=[.125,.25,.5,1,2];
const autoLabels={manual:'自分で決める',safe:'重要判断は確認',all:'すべておまかせ'};
let previewState,previewMode,previewOption;
function plannedChoice(){if(!autoReady())return null;if(previewState!==s||previewMode!==prefs.auto){previewState=s;previewMode=prefs.auto;previewOption=previewAutoChoice(s,prefs.auto);}return previewOption;}
function decisionStatus(){if(s?.decisionReceipt)return s.decisionReceipt.automatic?(clock.running?'結果を表示中 · まもなく日常へ':'結果表示を一時停止 · 再開できます'):'結果確認中 · 続けると再開';if(autoReady()&&clock.running)return `まもなく「${plannedChoice().title}」を選びます`;return autoReady()?'自動判断は一時停止 · 自分で選ぶか再開':'あなたの選択待ち · 選ぶまで時間は停止';}
function speedControls(){return `<div class="speed-switch" role="group" aria-label="時間の速さ">${speedValues.map(n=>`<button data-speed="${n}" aria-pressed="${clock.speed===n}">${speedLabel(n)}</button>`).join('')}</div>`;}
const monthNow=()=>s?(s.calendarMonth??s.q*3+(s.ui?.month||0)):0;
const liveDate=()=>monthNow()?`${Math.floor((monthNow()-1)/12)+1}年目 ${(monthNow()-1)%12+1}月末`:'創業の日';
const phase=()=>s?.decisionHeld&&s?.pending?'判断保留 · 時間は停止中':s?.decisionReceipt?(clock.running?'結果を表示中 · まもなく再開':'結果確認 · 時間は停止中'):progressState({exists:!!s,ended:!!s?.ended,suspended:!!s?.suspended,checkpoint:!!s?.checkpoint,wanted:clock.wanted,running:clock.running,pending:!!s?.pending,auto:!!autoReady(),remaining:clock.remaining,reading:readingPast});
function header(){return `<header class="topbar"><div class="top-row"><a class="brand" href="./">${esc(s?.name||'会社の一生')} <small>0.9.12</small></a>${s?'<button data-do="company">会社のこと</button>':'<button data-do="data">遊び方</button>'}</div>${s?`<div class="present-heading"><div><span class="eyebrow">創業から</span><strong class="company-age">${Math.floor(monthNow()/12)}<small>年</small>${monthNow()%12}<small>か月</small></strong></div><div class="current-president">${s.life?.version>=2?`第${currentLeader(s).number}代社長 <b>${esc(currentLeader(s).name)}</b>`:''}<small>${liveDate()}</small></div></div>${!s.ended&&!s.ui?.summary?playbackControls():''}`:''}</header>`;}
const footer=()=>'<footer>架空の会社のシミュレーション。実調査とモデル上の仮定を組み合わせています。</footer>';
function dock(action,label,hint,disabled=false){return `<div class="action-dock"><div><p>${hint}</p><button class="primary" data-do="${action}" ${disabled?'disabled':''}>${label}<span aria-hidden="true"> →</span></button></div></div>`;}
function playbackControls(){return `<div class="transport"><div class="playback-controls"><button class="play-toggle primary" data-do="toggle-play">${clock.wanted?'Ⅱ 停止':'▶ 再生'}</button>${speedControls()}<span class="phase" role="status">${phase()}</span><button class="auto-mode-control" data-do="play-settings">${autoLabels[prefs.auto]} · 設定</button><button class="step-control" data-do="step-month" ${s.pending||s.decisionReceipt||s.ended||s.checkpoint||s.suspended?'disabled':''}>1か月進める</button></div><div class="update-progress"><div class="update-caption"><span id="update-label">経過</span><span id="update-remaining" aria-hidden="true"></span></div><div id="update-meter" role="progressbar" aria-label="次の更新までの進行" aria-valuemin="0" aria-valuemax="100" aria-valuenow="0"><i id="update-fill"></i></div></div></div>`;}

function refreshPlayback(){document.querySelectorAll('[data-speed]').forEach(b=>b.setAttribute('aria-pressed',String(Number(b.dataset.speed)===clock.speed)));const mode=document.querySelector('.auto-mode-control');if(mode)mode.textContent=autoLabels[prefs.auto]+' · 設定';const status=document.querySelector('.phase');if(status)status.textContent=phase();const toggle=document.querySelector('.play-toggle');if(toggle){toggle.textContent=clock.wanted?'Ⅱ 停止':readingPast?'▶ 最新から再開':'▶ 再生';toggle.disabled=!!(s?.pending&&!autoReady()&&!s.decisionHeld);if(s?.decisionHeld)toggle.textContent='相談に戻る';}const pause=decisionModal.querySelector?.('[data-do="decision-pause"]');if(pause)pause.textContent=clock.wanted?'一時停止':'再開';refreshProgress();}
function refreshProgress(){
 if(progressFrame!==null){globalThis.cancelAnimationFrame?.(progressFrame);progressFrame=null;}
 const draw=()=>{const bar=document.querySelector('#update-meter'),fill=document.querySelector('#update-fill'),label=document.querySelector('#update-label'),remaining=document.querySelector('#update-remaining');if(!s||s.ended||!bar||!fill?.style)return;
 const decision=s.pending&&s.ui?.phase!=='review',waiting=decision&&!autoReady(),pct=waiting?0:Math.round(clock.progress*100);bar.setAttribute('aria-valuenow',String(pct));fill.style.transform=`scaleX(${pct/100})`;
 label.textContent=s.decisionReceipt?'結果の表示時間':decision?'判断までの経過':'1か月の経過';const status=document.querySelector('.phase');if(status)status.textContent=phase();
 const ds=decisionModal.querySelector?.('.dialog-state');if(ds)ds.textContent=decisionStatus();const line=decisionModal.querySelector?.('.decision-progress i');if(line)line.style.transform=`scaleX(${clock.progress})`;remaining.textContent='';
 if(clock.running&&globalThis.requestAnimationFrame)progressFrame=globalThis.requestAnimationFrame(draw);else progressFrame=null;
 };draw();
}
function syncClock(){clock.block('held',!!s?.decisionHeld&&!!s?.pending);clock.block('receipt',!!s?.decisionReceipt&&!s.decisionReceipt.automatic);clock.block('inactive',!s||!s.decisionReceipt&&(!!s.suspended||!!s.ended||!!s.ui?.summary||!!s.checkpoint&&prefs.auto==='manual'));clock.block('decision',!!s?.pending&&!s.decisionReceipt&&!autoReady());}
function persist(){if(!s||s.model!==MODEL)return;try{localStorage.setItem(KEY,JSON.stringify(s));saveError='';}catch{saveError='自動保存できません。「記録を書き出す」で保存してください。';}}
function exportFile(raw,name){const url=URL.createObjectURL(new Blob([raw],{type:'application/json'}));const a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}
function groupFor(state){return !state.timelineVersion&&state.model===MODEL&&cohort?.model===MODEL&&cohort?.dataVersion===state.config.version?cohort.groups[state.originId]:null;}
function bars(labels,values,index){const max=Math.max(...values,1);return `<div class="distribution">${labels.map((label,i)=>`<div class="bar-row ${i===index?'mine':''}"><span>${label}${i===index?' <b>← あなた</b>':''}</span><div class="bar-track"><i style="width:${values[i]/max*100}%"></i></div><strong>${values[i]}%</strong></div>`).join('')}</div>`;}
function realStart(state){const n=state.initial.staff+1,b=teamBucket(n),data=REAL_START;const insight=n===1?'この調査では、ひとりで始めた企業が最も多い。':n===2?'2人での開業は、この調査で2番目に多い人数です。':'3人での開業は、この調査では約9社に1社。最初から仲間と始める経歴です。';return `<section class="insight real"><div class="insight-heading"><span class="source-tag">実調査 · ${data.year}年度</span><span>開業時の人数 / 経営者を含む</span></div><h2>あなたの会社は、${n}人で始まる。</h2><p class="finding">${insight}</p>${bars(data.labels,data.values,b)}<p class="source-note">公庫融資先への調査・人数の回答 ${num(data.n)}社。個人企業を含みます。全企業・受託開発業の分布ではありません。</p><details><summary>出典・対象・比較できること</summary><p>${data.population}</p><p>${data.notes}</p><p>調査時点：${data.observed} / <a href="${data.url}#page=2" target="_blank" rel="noopener">${data.publisher}「${data.title}」p.1 ↗</a></p></details></section>`;}
function patternCard(state,record){const g=groupFor(state),count=g?.patterns?.[record.key],p=PATTERNS[record.key];if(!p)return '';const available=count?.eligible>=12;return `<section class="insight generated"><div class="insight-heading"><span class="source-tag">ゲーム内集計</span><span>同じ境遇・同じ選択条件</span></div><h3>${p.label}</h3><p class="finding">あなた：${record.continued?'対象の関係を、その後も続けた。':'対象の関係は、その後に残らなかった。'}</p><p>${dateAt(record.atMonth??record.at*3)}の判断 → ${dateAt(record.observedMonth??record.observedAt*3)}の決算、仕事量 ${num(record.loadBefore*100)}% → ${num(record.loadAfter*100)}%</p>${available?`<div class="ratio"><strong>${count.continued}<small> / ${count.eligible}社</small></strong><p>${p.outcome}。</p></div><div class="ratio-track" role="img" aria-label="${count.eligible}社中${count.continued}社が関係を継続"><i style="width:${count.continued/count.eligible*100}%"></i></div><p class="finding">${count.continued===count.eligible?'今回の比較記録では、全社に関係が残りました。次の会社でも続くという保証ではありません。':count.continued>0?'同じ種類の判断でも、その後の関係には違いが生まれています。':'今回の比較記録では、関係を続けた会社はありませんでした。'}</p>`:'<p class="finding">近い経歴の記録がまだ少ないため、割合や順位は付けません。あなたの選択と経過を残します。</p>'}<details><summary>何を揃えて比べたか</summary><p>${p.criteria}</p><p>境遇：${esc(state.origin.label)}。関係が残らなかった会社も含み、判断から2期後まで記録がない会社は除外。選択の効果を証明する比較ではありません。</p><button class="text-button" data-do="cohort">生成条件を見る</button></details></section>`;}
function momentInsight(state=s){if(state.q===0)return realStart(state);const records=experiencePatterns(state);const latest=records.filter(r=>(state.batch||[state.q]).includes(r.observedAt)).at(-1);if(latest)return patternCard(state,latest);const g=groupFor(state),q=g?.quarters?.[state.q];if(!q||q.count<12)return '<section class="insight generated"><span class="source-tag">ゲーム内集計</span><p>同じ時期の比較記録が不足しています。割合や順位は表示しません。</p></section>';const b=loadBucket(state.last.load),values=q.load.map(v=>Math.round(v/q.count*1000)/10);return `<section class="insight generated"><div class="insight-heading"><span class="source-tag">ゲーム内集計</span><span>同じ境遇・創業${state.q*3}か月時点</span></div><h2>仕事があることと、回せること。</h2><p class="finding">${state.last.load>1.1?`あなたの仕事量は能力の${num(state.last.load*100)}%。受注があっても、納める力が追いついていません。`:`あなたの仕事量は能力の${num(state.last.load*100)}%。${state.last.load<.8?'今の体制には、まだ仕事を受ける余地があります。':'今期は処理能力に近い量の仕事を進めました。'}`}</p>${bars(LOAD_LABELS,values,b)}<p>${q.load[b]}社 / ${q.count}社が、あなたと同じ仕事量の範囲でした。</p><p class="source-note">この時点で資金不足になっていない生成会社のみ。受注や採用の選択は同一ではありません。現実の企業の割合ではありません。</p><button class="text-button" data-do="cohort">比較条件を見る</button></section>`;}
function welcome(){
 if(!introducing){app.innerHTML=header()+`<main class="page entry-page"><p class="eyebrow">一社との出会いから</p><h1>この会社から、始めよう。</h1><p>誰と出会い、何を残す会社になるだろう。</p><button class="primary" data-do="start">始める</button>${brokenRaw?`<p>${esc(saveError)} <button data-do="export-broken">元の記録を書き出す</button></p>`:''}${legacy?'<a href="legacy-v02/">以前の版の記録</a>':''}</main>`;return;}
 const o=draft.origin;app.innerHTML=header()+`<main class="page encounter-stage"><p class="eyebrow">今回めぐりあった一社</p><h1>${esc(draft.name)}</h1>${castView(draft)}<p class="encounter-summary">${esc(draft.encounter.summary)}</p><p>${esc(o.description)}</p>${startModes()}<button class="primary" data-do="begin-story">${prefs.auto==='manual'?'自分で決めながら始める':'おまかせで始める'}</button><button class="text-button" data-do="reroll">別の出会いを見る</button><small>架空の人物・境遇の抽選です。実企業の分布とは異なります。</small></main>`;
}
const modeLabels={manual:'自分で決める',safe:'おまかせ・資金と終了は確認',all:'すべておまかせ'};
function startModes(){return `<section class="start-mode"><h2>今回は、どう見守る？</h2><p>今回の操作：<b>${modeLabels[prefs.auto]}</b>。開始するまで時間も判断も進みません。</p><div class="setting-buttons">${Object.entries(modeLabels).map(([key,label])=>`<button data-start-mode="${key}" aria-pressed="${prefs.auto===key}">${label}</button>`).join('')}</div><small>おまかせでは、選択予定を見ている間に介入できます。選択肢に触れると、自分で決められます。</small></section>`;}
function castView(state){return `<div class="encounter-cast" aria-label="今回の会社の関係"><article style="--order:0"><span>01 創業者</span><b>${esc(state.founder?.name||'創業者')}</b><p>${state.experience}年の経験 · ${esc(state.origin.region)}</p></article><article style="--order:1"><span>02 最初の仲間</span><b>${state.people.length?state.people.map(p=>esc(p.name)).join('・'):'ひとりからの出発'}</b><p>${state.people.length?esc(state.encounter?.relation):'最初の仲間との出会いは、これから。'}</p></article><article style="--order:2"><span>03 最初の取引</span><b>${state.clients.length?state.clients.map(c=>esc(c.name)).join('・'):esc(state.contacts[0]?.name||'これから探す')}</b><p>${state.clients.length?'この相手との契約が、会社の出発点。':'試作の相談。継続契約はまだありません。'}</p></article></div>`;}
function capacity(){return s.q?s.last.capacity:(s.config.parameters.capacityPerPerson+activeTeam(s).reduce((n,p)=>n+personCapacity(s,p),0))*s.skill;}
function metrics(){return `<section class="metrics" aria-label="判断に使う会社の状態"><div><span>手元資金</span><b class="${s.cash<costs(s)*1.3?'warning':''}">${money(s.cash)}</b><small>通常費用 ${money(costs(s))}/3か月</small></div><div><span>納品できる仕事量${s.q?'（直近期）':''}</span><b>${money(capacity())}/期</b><small>1期＝3か月・売上換算</small></div><div><span>能力に対する仕事量</span><b class="${s.last.load>1.1?'warning':''}">${s.q?num(s.last.load*100)+'%':'未観測'}</b><small>積み残し ${money(s.backlog)}</small></div><div><span>一緒に働く人 / 顧客</span><b>${staff(s)+1}人 / ${activeClients(s).length}社</b><small>借入 ${money(s.debt)}</small></div></section>`;}
function eventView(e,{dated=true}={}){const d=eventDigest(s,e);return `<article class="diary-event ${d.significant?'significant':''}">${dated?`<p class="event-meta">${e.month!==undefined?dateAt(e.month):period(e.q)}</p>`:''}<details class="diary-detail" data-diary-detail="${e.id}"><summary><span class="diary-sentence">${d.significant?'<span class="turning-mark">転機</span>':''}${esc(d.title)}${d.scale?` <strong class="diary-scale">${esc(d.scale)}</strong>`:''}${d.participants.length?` <span class="diary-related">（関係者：${d.participants.map(esc).join('・')}）</span>`:''}</span><span class="expand-mark" aria-hidden="true">＋</span><span class="sr-only"> — 詳細を開閉</span></summary><div class="diary-notes"><p>${esc(e.text)}</p>${e.context?`<p>${esc(e.context)}</p>`:''}${d.founders.length?`<p>${d.founders.map(esc).join('・')} · 創業からの仲間</p>`:''}${d.previous?`<button class="memory-link" data-event="${d.previous.id}">関連する記録：${esc(eventSummary(s,d.previous).title)}</button>`:''}${e.causes?.length||e.entities?.length?`<button class="causal-link" data-event="${e.id}">この出来事までの経緯</button>`:''}</div></details></article>`;}

function recentEvents(){const qs=s.batch?.length?s.batch:[s.q],events=s.events.filter(e=>qs.includes(e.q)&&e.kind!=='world'),important=events.filter(e=>e.major||e.kind==='start'),routine=events.filter(e=>!e.major&&e.kind!=='start');return important.map(eventView).join('')+(routine.length?`<p class="routine-summary">通常の仕事・連絡 ${routine.length}件。${[...new Set(routine.flatMap(e=>e.entities).map(id=>s.clients.find(c=>c.id===id)?.name).filter(Boolean))].slice(0,3).map(esc).join('、')}との仕事を重ねました。内容は履歴に残っています。</p>`:'')||'<p>大きな出来事はなく、通常の仕事と支払いを重ねました。</p>';}
function supportPanel(){if(s.pending?.initiated||['cyber','rescue','exit','successor','strategy','handover'].includes(s.pending?.type))return '';const list=problems(s);if(s.timelineVersion&&!s.ended&&!list.some(p=>p.id==='workload'))list.push({id:'workload',title:'受注・採用を調整する',text:'今の仕事量や、これからの体制を自分から見直せます。'});return list.length?`<section class="support-panel"><h2>今、対処できること</h2>${list.map(p=>`<article><div><h3>${esc(p.title)}</h3><p>${esc(p.text)}</p></div><button data-help="${p.id}">対処を選ぶ <small>時間は進みません</small></button></article>`).join('')}${s.threads.some(t=>['join','recruit','annualRecruit'].includes(t.type))?'<p>採用の結果・入社を待っています。</p>':''}${s.workPlan?.until>s.q?'<p>次の季節も受注を絞る方針が続きます。</p>':''}</section>`:'';}
function playerOptionText(d,a){if(s.life?.version>=2&&['hire','recruit'].includes(a.id))return '1人を募集。入社の目安は2〜12か月。1年活動しても採用に至らない場合があります。給与は入社後から。';return a.desc.replace(/本人の負担 [−-]30。/g,'本人の負担を軽くする。');}
function choiceView(d){const allowed=new Set(availableDecisionOptions(s).map(a=>a.id));return `<section class="decision-panel"><p class="eyebrow">${liveDate()}</p><h1 tabindex="-1" id="decision-title">${esc(d.title)}</h1><div class="decision-layout player-decision"><div class="decision-background"><p class="decision-context">${esc(d.text.length>140?d.text.split("。")[0]+"。":d.text)}</p>${decisionContext(d)}</div><div class="decision-actions"><h2 class="options-label">対応を選ぶ</h2><div class="decision-options" role="group" aria-label="対応を選ぶ">${d.options.map((a,i)=>`<article data-option="${a.id}" class="option-row ${isLightChoice(d,a)?'quick-reply':'confirm-choice'} ${selected===a.id?'selected':''}"><button class="story-choice ${isLightChoice(d,a)?'reply-action':'candidate-choice'} ${selected===a.id?'selected':''}" data-choice="${a.id}" ${allowed.has(a.id)?'':'disabled'} aria-pressed="${selected===a.id}"><span class="choice-title"><i>${isLightChoice(d,a)?'→':selected===a.id?'●':'○'}</i><strong>${esc(a.title)}</strong><b class="choice-cost">${a.cost?money(a.cost):'初期費用なし'}</b></span><span class="choice-effect">${esc(playerOptionText(d,a))}</span><small class="choice-mode">${isLightChoice(d,a)?'即時返答 →':'確認して決定'}</small>${allowed.has(a.id)?'':'<small>現在の資金または採用予定などの条件では実行できません</small>'}</button><details data-detail="risk-${a.id}"><summary>主なリスク・条件</summary><p>${esc(a.effect)}</p>${s.life?.version>=2&&['hire','recruit'].includes(a.id)?'<p>入社までの2〜12か月はゲーム上の仮定です。年間の採用計画達成率とは別に設定しています。</p>':''}</details></article>`).join('')}</div></div></div>${decisionDiscovery(d)}${d.text.length>140?`<details data-detail="background"><summary>相談の背景</summary><p>${esc(d.text)}</p></details>`:''}${d.initiated?'<button data-do="cancel-help">対処をやめて元の相談へ戻る</button>':''}</section><details><summary>自分から別の対処を検討する</summary>${supportPanel()}</details>`;}

function changes(){const from=s.ui?.fromQ??Math.max(0,s.q-(s.batch?.length||1)),before=s.history.find(h=>h.q===from),cash=before?.cash??s.initial.cash,people=before?before.staff+1:s.initial.staff+1;return `<section class="change-summary"><div><span>手元資金</span><strong>${money(cash)} → ${money(s.cash)}</strong></div><div><span>一緒に働く人数</span><strong>${people}人 → ${staff(s)+1}人</strong></div><div><span>最後の3か月の利益</span><strong>${money(s.last.profit)}</strong></div></section>`;}
function nextAction(){if(!forecast||forecast.state!==s)forecast={state:s,...continuation(s,x=>advance(x,1))};return forecast;}
function workProgress(){const m=s.ui?.month||0,contracts=s.contracts.filter(k=>k.active);return `<section class="work-progress"><div class="month-steps" aria-label="次の3か月決算までの月の経過">${[1,2,3].map(n=>`<span class="${m>=n?'elapsed':''}">${n<3?`${n}か月経過`:'3か月・決算'}</span>`).join('')}</div><p>次の決算まで ${3-m}か月。案件を進め、納品と入金を待っています。</p>${contracts.length?contracts.map(k=>`<div class="project-progress"><b>${esc(s.clients.find(c=>c.id===k.clientId)?.name||'開発案件')}</b><span>予定期間の経過 ${Math.min((k.end-k.start+1)*3,Math.max(0,(s.q-k.start+1)*3+m))} / ${(k.end-k.start+1)*3}か月</span></div>`).join(''):`<p class="source-note">${activeClients(s).length?activeClients(s).map(c=>esc(c.name)).join('・')+'の仕事を進めています。':'最初の継続顧客との出会いを待っています。'}</p>`}<p class="source-note">月の表示は経過の演出です。受注・納品・入金・会計は3か月単位で確定します。</p></section>`;}
function briefInsight(){const g=groupFor(s),q=g?.quarters?.[s.q];if(!q||q.count<12)return '';return `<p class="brief-insight"><span class="source-tag">ゲーム内集計</span> 同じ境遇・創業${s.q*3}か月の${q.count}社中${q.load[loadBucket(s.last.load)]}社が、あなたと同じ仕事量の範囲（${LOAD_LABELS[loadBucket(s.last.load)]}）。受注量と体制の釣り合いを比べられます。</p>`;}
function observe(){return `<section class="current-scene"><p class="eyebrow">${esc(s.name)} · ${esc(chapter(s))}</p><h1 id="scene-title" tabindex="-1">${s.q===0?'この会社の時間が、動き始めます。':'いつもの仕事が、次の出来事につながる。'}</h1></section>${workProgress()}${metrics()}${supportPanel()}${s.q===0?`<section class="origin-note"><h2>今回の出発点</h2><p>${esc(s.origin.description)}</p></section>`:`<section class="last-report"><h2>直前の決算 · ${period(s.q)}</h2><p>納品 ${money(s.last.revenue)} / 入金 ${money(s.last.collections)} / 利益 ${money(s.last.profit)}</p></section>`}${momentInsight()}`;}
const dateAt=m=>m?`${Math.floor((m-1)/12)+1}年目 ${(m-1)%12+1}月末`:'創業の日';
function parallelWork(){const list=schedules(s).sort((a,b)=>a.month-b.month),row=r=>`<li class="${changeCue?.month===monthNow()&&changeCue.work.some(id=>r.key==='contract:'+id)?'place-changed':''}"><span>${esc(r.label)}</span><b>${r.month>monthNow()?`あと${r.month-monthNow()}か月`:'確認時期'}</b><small>${dateAt(r.month)}</small></li>`;return `<section class="parallel-work"><h2>進んでいる仕事・予定</h2><ul>${list.slice(0,3).map(row).join('')}</ul>${list.length>3?`<details><summary>ほか${list.length-3}件の予定</summary><ul>${list.slice(3).map(row).join('')}</ul></details>`:''}${receivables(s)?`<p class="waiting-money">入金待ち ${money(receivables(s))}</p>`:''}${!list.length&&!receivables(s)?'<small>期限付きの予定なし</small>':''}${changeCue?.month===monthNow()?changeCue.done.map(k=>`<p class="work-completed place-changed">✓ ${esc(s.clients.find(c=>c.id===k.clientId)?.name||'案件')} · ${k.kind==='trial'?'試作期間':'契約期間'}終了</p>`).join(''):''}</section>`;}
function realMoment(key){const d=REAL_MOMENTS[key];return `<section class="real-moment"><span class="source-tag">実調査 · 2025年度 / 関連する経験の参考</span><h3>${d.title}</h3>${d.labels.map((label,i)=>`<div class="stat-line"><span>${label}</span><b>${d.values[i]}%</b><div class="stat-scale" role="img" aria-label="${label} ${d.values[i]}%"><i style="width:${d.values[i]}%"></i></div></div>`).join('')}<p>${d.finding}</p><details><summary>対象・時点・出典を確認</summary><p>${REAL_START.population}</p><p>調査は2025年8月。回答企業の開業後経過月数は平均15.5か月で、この会社と同じ年数・業種に限定した比較ではありません。本項目の回答数 ${d.n.toLocaleString('ja-JP')}社。</p><p>${d.limit}</p><p>全企業の分布でも、ゲーム内の集計でもありません。</p><a href="${REAL_START.url}#page=${d.page+1}" target="_blank" rel="noopener">日本政策金融公庫「2025年度新規開業実態調査」p.${d.page} 図${d.figure}</a></details></section>`;}
function discovery(key){let line='',detail='';
 if(REAL_MOMENTS[key]){const d=REAL_MOMENTS[key];line=key==='growth'?'公庫融資先の新規開業企業では、売上が横ばい・減少傾向の回答が39.9%。成長の道筋は一様ではありません。':`公庫融資先の新規開業企業の${d.values[0]}%が「${d.labels[0]}」と回答。${key==='hiring'?'人を探す苦労は、この会社だけではありません。':'採用後にも、人を育てる課題が続きます。'}`;detail=realMoment(key);}
 if(key==='start'){const n=s.initial.staff+1,i=teamBucket(n);line=`公庫融資先の新規開業企業で、${REAL_START.labels[i]}での開業は${REAL_START.values[i]}%。今回の会社は${n}人から。`;detail=realStart(s);}
 if(key==='cyber'){line='IPA調査の小規模企業では、年間のインシデント経験は自己診断70点以上群12.2%、69点以下群17.1%。対策があっても、経験ゼロとは限りません。';detail=evidenceCard('cyber','<p>群間の違いは対策購入の効果の証明ではありません。ゲームの月率への換算は推計、軽微・一部・全面の内訳と費用・復旧期間は仮定です。</p>');}
 if(key==='annualHiring'){line='公庫取引先・49人以下の採用実施企業では、年間計画未達が31.9%。候補者1人の失敗率ではありません。';detail=evidenceCard('hiring','<p>この会社の1名計画への適用は推計。入社時期は別の仮定です。</p>');}
 if(key==='succession'){line='承継した兵庫県の信用保証協会利用企業610社では、当期利益が承継時から減少した回答は17.2%。交代は成長の保証ではありません。';detail=successionEvidence();}
 return line?`<aside class="discovery"><span class="source-tag">実調査 · この出来事から</span><p>${line}</p><details><summary>対象・調査年・出典・利用上の限界</summary>${detail}<p>自社の成功確率・順位を示す数字ではありません。</p></details></aside>`:'';
}
function timelineRecords(fromMonth=0){
 const assignments=discoveryAssignments(s);const records=s.events.filter(e=>(e.month??e.q*3)>=fromMonth).map((e,i)=>({id:e.id,month:e.month??e.q*3,order:i,html:`<div class="timeline-entry ${eventDigest(s,e).significant?'major':'routine'}" tabindex="-1" data-record="${e.id}">${eventView(e,{dated:false})}${assignments.has(e.id)?discovery(assignments.get(e.id)):''}</div>`}));
 for(const h of s.history.filter(h=>h.q*3>=fromMonth))records.push({id:'settlement'+h.q,month:h.q*3,order:100000+h.q,html:`<article class="timeline-entry settlement"><details class="diary-detail"><summary><span class="diary-sentence"><span class="diary-kind">四半期決算</span> 納品 ${money(h.revenue)} · 入金 ${money(h.collections)} · <strong>利益 ${money(h.profit)}</strong></span><span class="expand-mark" aria-hidden="true">＋</span><span class="sr-only"> — 決算の詳細を開閉</span></summary><div class="diary-notes"><p>${dateAt(h.q*3)}時点：手元 ${money(h.cash)} · ${h.staff+1}人体制。直前3か月の集計です。</p><button data-do="company">現在の会計を見る</button></div></details></article>`});
 if(monthNow()>=15&&fromMonth<=15)records.push({id:'growth-observation',month:15,order:200000,html:`<article class="timeline-entry"><p class="event-line">直近2期の売上：${money(s.history.find(h=>h.q===4)?.revenue||0)} → ${money(s.history.find(h=>h.q===5)?.revenue||0)}</p>${discovery('growth')}</article>`});
 for(let m=Math.max(60,Math.ceil(fromMonth/60)*60);m<=monthNow();m+=60){const departed=s.people.filter(p=>!p.active&&personLeftMonth(s,p)>m-12&&personLeftMonth(s,p)<=m).length;records.push({id:`anniversary-${m}`,month:m,order:300000,html:`<article class="timeline-entry anniversary"><p class="event-line"><b>創業${m/12}年。</b>直近1年間に会社を離れた仲間は${departed}人。</p><aside class="discovery"><p>公庫取引先・従業者49人以下の回答2,338社では、2025年度の退職者が0人だった企業は45.4%。${departed===0?'人が残り続けた1年も、会社の歩みの一つです。':'入社だけでなく、別れも会社の体制を変えてきました。'}</p><details><summary>実調査の対象・年度と、この会社の集計</summary><p>${dateAt(m-12)}から${dateAt(m)}までのゲーム内の退職・離職記録。実調査は2025年度の企業別退職者数（公庫中小企業事業取引先）。期間の長さは1年ですが、企業規模・業種・時代は一致しません。あなたの会社の順位や、個人の退職確率ではありません。</p><a href="${EVIDENCE.departures.url}" target="_blank" rel="noopener">日本政策金融公庫「中小企業における従業員の採用・定着に関する調査」2026年3月調査 · ${EVIDENCE.departures.page} ↗</a></details></aside></article>`});}
 return records.sort((a,b)=>a.month-b.month||a.order-b.order);
}
function companyFaces(){const recent=new Set(s.events.filter(e=>(e.month??e.q*3)>=monthNow()-3).flatMap(e=>e.entities||[])),people=activeTeam(s).slice().sort((a,b)=>Number(changeCue?.people.includes(b.id))-Number(changeCue?.people.includes(a.id))||Number((b.strain||0)>=40)-Number((a.strain||0)>=40)||Number(recent.has(b.id))-Number(recent.has(a.id))),clients=activeClients(s).slice().sort((a,b)=>clientWork(s,b)-clientWork(s,a)||Number(recent.has(b.id))-Number(recent.has(a.id)));return `<section class="company-faces"><h2>この会社の人と取引</h2><p class="list-scope">在籍する仲間 ${people.length}人 · 入社・負担の変化を優先${people.length>2?`（ほか${people.length-2}人）`:""}</p>${people.slice(0,2).map(p=>`<article class="${changeCue?.month===monthNow()&&changeCue.people.includes(p.id)?'place-changed':''}"><span class="name-mark" aria-hidden="true">${esc(p.name.slice(0,1))}</span><div><b>${esc(p.name)}${changeCue?.month===monthNow()&&changeCue.people.includes(p.id)?' <em class="new-person">入社</em>':''}</b><small>${p.founding?'創業から一緒':dateAt(personJoinedMonth(s,p))+'に入社'} · ${Math.max(0,monthNow()-personJoinedMonth(s,p))}か月</small><small class="person-condition ${personCondition(p).level}">${esc(personCondition(p).text)}</small></div></article>`).join('')}<p class="list-scope">継続顧客 ${clients.length}社 · 基準受注の大きい順${clients.length>2?`（ほか${clients.length-2}社）`:""}</p>${clients.slice(0,2).map(c=>{const prior=s.events.filter(e=>(e.entities||[]).includes(c.id)&&e.topic==='relationship').at(-1);return `<article><span class="name-mark client-mark" aria-hidden="true">${esc(c.name.slice(0,1))}</span><div><b>${esc(c.name)}</b><small>継続取引 · 基準受注 ${money(clientWork(s,c))}／期</small>${prior?`<button class="memory-link" data-event="${prior.id}">${esc(prior.title)}</button>`:''}</div></article>`;}).join('')}<button class="text-button" data-do="relationships">人と取引を全件見る</button></section>`;}
function compactStatus(){return `<aside class="current-status"><p class="eyebrow">${liveDate()} · 現在の会社</p><div class="company-identity"><b>${esc(currentLeader(s)?.name||s.founder?.name||"創業者")} 社長</b><span>${s.style==='companion'?'保守中心・既存の取引を育てる':s.style==='delegated'?'仲間と役割を分担':s.style==='hands-on'?'社長も現場へ':'今ある仕事を積み重ねる'}${s.workPlan?.until>=s.q?' · 受注を調整中':''}</span></div><section class="company-pulse" aria-label="今月の状態">${[['資金',money(s.cash),'cash'],['借入',money(s.debt),'debt'],['社員',staff(s)+'人'],['顧客',activeClients(s).length+'社']].map(([label,value,key])=>`<div class="${changeCue?.month===monthNow()&&changeCue[key]?'place-changed':''}"><span>${label}</span><b>${value}</b>${changeCue?.month===monthNow()&&changeCue[key]?`<small>${liveDate()}の更新 ${changeCue[key]>0?'+':''}${money(changeCue[key])}</small>`:''}</div>`).join('')}</section><p class="state-note">${s.last.q?dateAt(s.last.q*3):period(s.q)}の決算：納品 ${money(s.last.revenue)}／期<br>現在の積み残し ${money(s.backlog)}</p>${companyFaces()}${parallelWork()}</aside>`;}
function diaryView(records){return `<section class="company-diary" aria-labelledby="diary-title"><div class="diary-heading"><h1 id="diary-title" tabindex="-1">会社の日誌</h1><span>直近5年分 · 新しい順</span></div><p class="diary-range">${monthNow()>=60?`${dateAt(Math.max(0,monthNow()-59))}以降を表示。`:""}全期間の記録は振り返りに残ります。</p><div class="diary-now"><span>${liveDate()}${!records.some(r=>r.month===monthNow())?` · 次の決算まで${3-monthNow()%3}か月`:''}</span>${quickNotice?`<span role="status">✓ 返答を記録しました：${esc(quickNotice)}</span>`:''}<button data-do="latest" class="diary-latest" ${readingPast||unread?'':'hidden'}>${unread?`新着 ${unread}件 · `:''}最新へ戻る</button></div><div id="life-feed" class="diary-feed" tabindex="0" aria-label="会社の日誌・新しい順">${diaryMonths(records).map(g=>`<section class="diary-month"><h2>${dateAt(g.month)}${g.month===monthNow()?'<span>今月</span>':''}</h2>${g.records.map(r=>r.html).join('')}</section>`).join('')||'<p>この先の出来事が、ここに残ります。</p>'}</div>${s.ended||s.checkpoint?'<button class="primary" data-do="summary">最後の出来事を確認して、振り返る</button>':''}</section>`;}

function decisionContext(d){
 const finance=['finance','crisis','rescue','exit'].includes(d.type),b=orderBudget(s),hiring=d.options.some(a=>['hire','welcome','recruit','inhouse'].includes(a.id))||['hiring','workload','large'].includes(d.type);
 if(finance)return `<div class="decision-evidence"><p>手元 <b>${money(s.cash)}</b> ／ 借入 <b>${money(s.debt)}</b><br>入金待ち ${money(receivables(s))} ／ 通常費用 ${money(costs(s))}・3か月分</p><p>借入は現金と負債を同額増やします。利益には含めず、利息・返済は後日発生します。</p></div>`;
 if(!hiring)return `<div class="decision-evidence">手元資金 <b>${money(s.cash)}</b> · ${staff(s)+1}人体制</div>`;
 const ending=s.contracts.filter(k=>k.end*3>=monthNow()&&k.end*3<=monthNow()+3),hires=s.threads.filter(t=>['join','recruit','annualRecruit'].includes(t.type));
 return `<div class="decision-evidence"><p>${staff(s)+1}人体制 · <b>次期の受注目安 ${money(b.committed)}／期</b><br>今の能力 ${money(b.capacity)}／期 · 積み残し ${money(b.backlog)}<br>手元 ${money(s.cash)} · 通常費用 ${money(costs(s))}／期</p>${ending.length||hires.length?`<p class="upcoming-summary">${ending.length?ending.map(k=>`${esc(s.clients.find(c=>c.id===k.clientId)?.name||'取引先')}：${money(k.value)}／期、${dateAt(k.end*3)}${k.end*3===monthNow()?'に終了':'まで'}`).join('<br>'):''}${ending.length&&hires.length?'<br>':''}${hires.length?hires.map(t=>`${esc(t.name||'採用計画')}：${dateAt(t.dueMonth??t.due*3)} ${t.type==='join'?'入社予定':'結果待ち（未確定）'}`).join('<br>'):''}</p>`:''}<small>受注は変動する見込み。今回の追加案件は含まず、積み残しは別枠。直近稼働 ${s.q?num(s.last.load*100)+'%':'未観測'}。</small></div>`;
}
function decisionDiscovery(d){if(['hiring','workload','large'].includes(d.type)&&d.options.some(a=>['hire','welcome','recruit'].includes(a.id))&&!s.decisions.some(x=>['hire','welcome','recruit'].includes(x.choiceId)))return discovery('hiring');if(d.type==='successor'&&s.life?.generations.length===1)return discovery('succession');return '';}
function receiptView(r){return `<h1 id="decision-title" tabindex="-1">${esc(r.action)}</h1><p class="eyebrow">${dateAt(r.month)}${r.automatic?' · おまかせの返答':''}</p>${r.outcomes?.length||r.changes.length?'<h2>今変わったこと</h2>':''}${r.outcomes?.length?`<div class="receipt-outcomes">${r.outcomes.map(x=>`<p>${esc(x.replace(/（[\d,.]+ → [\d,.]+ \/ 100）/g,''))}</p>`).join('')}</div>`:''}${r.changes.length?`<div class="receipt-changes">${r.changes.map(x=>`<p>${esc(x)}</p>`).join('')}</div>`:''}${r.future.length?`<h2>これから届くこと</h2><ul>${r.future.map(x=>`<li>${esc(x)}</li>`).join('')}</ul>`:''}${r.events.length?`<details><summary>対応の詳細</summary>${r.events.map(e=>`<p>${esc(e.text)}</p>`).join('')}</details>`:''}${receiptDiscovery(r)}${s.pending?`<p>次の相談：${esc(s.pending.title)}</p>`:''}`;}

function receiptDiscovery(r){const map=discoveryAssignments(s),key=r.events.map(e=>map.get(e.id)).find(Boolean);return key?discovery(key):'';}
let dialogKey='';
function renderDecision(){const r=s?.decisionReceipt,d=s?.pending;if(s?.decisionHeld&&d&&!r){if(decisionModal.open)decisionModal.close();return;}if(!r&&!d){if(decisionModal.open)decisionModal.close();dialogKey='';return;}
 const key=r?'result:'+r.eventId:'decision:'+d.id;if(key===dialogKey&&dialogState===s){if(!decisionModal.open)decisionModal.showModal();updateDecisionSelection();clock.block('decision-reading',!!decisionModal.querySelector?.('details[open]'));return;}const bodyScroll=key===dialogKey?(decisionModal.querySelector?.('.decision-body')?.scrollTop||0):0,opened=key===dialogKey?[...(decisionModal.querySelectorAll?.('details[open]')||[])].map(d=>d.dataset.detail||d.querySelector('summary')?.textContent):[];
 const a=d&&availableDecisionOptions(s).find(a=>a.id===selected);
 decisionModal.innerHTML=`<div class="decision-shell"><header class="decision-modal-head"><b>${r?'選択の結果':'相談'}</b>${!r?'<button data-do="hold-decision">いったん畳んで会社を見る</button>':''}${(r?.automatic||!r&&autoReady())?`<button data-do="decision-pause">${clock.wanted?'一時停止':'再開'}</button>`:''}</header><div class="decision-body">${r?receiptView(r):choiceView(d)}</div><footer class="decision-modal-foot"><div class="decision-feedback"><p class="dialog-state" role="status">${esc(decisionStatus())}</p>${(r?.automatic||!r&&autoReady())?'<div class="decision-progress" aria-hidden="true"><i></i></div>':''}</div>${r?`<button class="primary" data-do="continue-result">${s.ended||s.suspended?'結果を確認する':s.pending?'次の相談へ':'続ける'}</button>`:`<button class="primary" data-do="decide" ${a?'':'disabled'}>${a?esc(a.title)+' · 確定':'対応を選んでください'}</button>`}</footer></div>`;
 if(!decisionModal.open)decisionModal.showModal();const body=decisionModal.querySelector?.('.decision-body');if(body)body.scrollTop=bodyScroll;if(dialogKey!==key){decisionModal.querySelector?.('#decision-title')?.focus({preventScroll:true});}dialogKey=key;dialogState=s;for(const detail of decisionModal.querySelectorAll?.('details')||[])detail.open=opened.includes(detail.dataset.detail||detail.querySelector('summary')?.textContent);clock.block('decision-reading',opened.length>0);
}
function updateDecisionSelection(){
 const chosen=availableDecisionOptions(s).find(a=>a.id===selected);
 for(const b of decisionModal.querySelectorAll?.('[data-choice]')||[]){const yes=b.dataset.choice===selected;b.setAttribute('aria-pressed',String(yes));b.classList.toggle('selected',yes);b.closest('.option-row')?.classList.toggle('selected',yes);const mark=b.querySelector('i');if(mark)mark.textContent=isLightChoice(s.pending,s.pending.options.find(a=>a.id===b.dataset.choice))?'→':yes?'●':'○';}
 const confirm=decisionModal.querySelector?.('[data-do="decide"]');if(confirm){confirm.disabled=!chosen;confirm.textContent=chosen?chosen.title+' · 確定':'対応を選んでください';}
 const pause=decisionModal.querySelector?.('[data-do="decision-pause"]');if(pause)pause.textContent=clock.wanted?'一時停止':'再開';refreshPlayback();
}
function quickDecision(){const option=availableDecisionOptions(s).find(a=>a.id===selected);if(!isLightChoice(s.pending,option))return;const action=option.title;progress(()=>{const n=registerDecision(s,selected);delete n.decisionHeld;return n;});quickNotice=action;clock.restart();render();focusScene();if(!s.ended&&!s.suspended)clock.play();}
function decide(automatic=false){if(s.decisionReceipt)return;let lightReply='';progress(()=>{const before=s,n=automatic?autoDecision(s,prefs.auto):registerDecision(s,selected);if(n===s)return n;const last=n.events.filter(e=>!before.events.some(x=>x.id===e.id)),picked=n.decisions.at(-1),changes=[];for(const [label,a,b,unit] of [['手元資金',before.cash,n.cash,'万円'],['借入残高',before.debt,n.debt,'万円'],['社員',staff(before),staff(n),'人'],['顧客',activeClients(before).length,activeClients(n).length,'社']])if(a!==b)changes.push(`${label}：${num(a)} → ${num(b)}${unit}（${b>a?'+':''}${num(b-a)}${unit}）`);
 if(automatic&&isLightChoice(before.pending,before.pending.options.find(a=>a.id===picked?.choiceId))){lightReply=n.autoLast?.title||picked?.choice;return n;}
 const future=changedSchedules(before,n).map(r=>`${r.label}：${dateAt(r.month)}`);
 n.decisionReceipt={eventId:last.at(-1)?.id||`${n.calendarMonth}-${n.decisions.length}`,month:n.calendarMonth,title:before.pending.title,action:automatic?n.autoLast?.title:(before.pending.options.find(a=>a.id===selected)?.title||picked?.title),automatic,changes,outcomes:decisionOutcomes(before,n),events:last,future};delete n.helpReturnUi;return n;});if(lightReply){quickNotice=lightReply;render();}clock.restart();}
function continueResult(){if(!s.decisionReceipt)return;const eventId=s.decisionReceipt.eventId;delete s.decisionReceipt;readingPast=false;selected=null;persist();clock.restart();render();focusScene();document.querySelector(`[data-record="${eventId}"]`)?.focus({preventScroll:true});if(!s.ended&&!s.suspended)clock.play();}
function render(){
 syncClock();if(!s){welcome();return;}if((s.ended||s.checkpoint||s.suspended)&&!s.pending&&s.ui?.summary&&!s.decisionReceipt){renderDecision();result();return;}
 const position=readingPast?(document.querySelector('#life-feed')?.scrollTop||0):0,records=timelineRecords(Math.max(0,monthNow()-59)).reverse(),total=s.events.length+s.history.length+(monthNow()>=15?1:0)+Math.floor(monthNow()/60);
 const opened=[...(app.querySelectorAll?.('details[data-diary-detail][open]')||[])].map(d=>d.dataset.diaryDetail);
 if(readingPast)unread+=Math.max(0,total-seenRecords);else unread=0;seenRecords=total;
 app.innerHTML=header()+`<main class="page timeline-page">${saveError?`<p class="notice">${esc(saveError)}</p>`:''}<div class="present-layout"><div class="events-column">${diaryView(records)}</div>${compactStatus()}</div>${footer()}</main>`;
 for(const id of opened){const detail=app.querySelector(`[data-diary-detail="${id}"]`);if(detail)detail.open=true;}
 const feed=document.querySelector('#life-feed');if(feed){feed.scrollTop=position;let intent=false;for(const type of ['wheel','touchmove','pointerdown','keydown'])feed.addEventListener(type,()=>{intent=true;},{passive:true});feed.addEventListener('scroll',()=>{if(historyReadIntent({intent,top:feed.scrollTop})){readingPast=true;clock.pause();const back=document.querySelector('.diary-latest');if(back)back.hidden=false;}},{passive:true});}

 renderDecision();clock.block('reading',!!app.querySelector('details[open]'));refreshPlayback();measureJournalHeader();
}
function autoTick(){if(s?.decisionReceipt){if(s.decisionReceipt.automatic&&!document.hidden&&!modal.open)continueResult();return;}if(!s||s.decisionHeld||s.suspended||s.ended||document.hidden||modal.open)return;if(s.pending){if(autoReady())decide(true);return;}if(s.checkpoint){if(prefs.auto!=='manual')progress(()=>continueLife(s),{automatic:true});return;}progress(()=>tickMonth(s),{automatic:true});}
function timeline(all=false){if(all)return s.events.map(eventView).join('');return storyChapters(s).map(c=>`<section class="story-chapter"><p class="eyebrow">${dateAt(decisionMonth(s,c.decision))}の選択 → その後</p><h2>${esc(c.title)}</h2>${c.events.filter(e=>e.id===c.decision.eventId||e.kind==='turning'||e.kind==='risk').map(eventView).join('')}<details><summary>この選択までの経緯をすべて見る</summary>${c.events.map(eventView).join('')}</details></section>`).join('')||s.events.map(eventView).join('');}
function remainingIssues(){const resolved=s.events.filter(e=>e.topic==='response'||e.kind==='turning'&&e.topic==='people');const issues=[...(s.life?.recoveryUntil?[`${dateAt(s.life.recoveryUntil)}まで業務復旧中`]:[]),...(s.life?.claimDue?[`保険補填${money(s.life.claimAmount)}の入金待ち`]:[]),...(s.life?.advanceLiability?[`前受金${money(s.life.advanceLiability)}の納品・返金義務`]:[]),...s.threads.filter(t=>['join','recruit','annualRecruit','negotiation','improve','workReview'].includes(t.type)).map(t=>`${({join:'入社',recruit:'採用',annualRecruit:'年間採用計画',negotiation:'交渉',improve:'引継ぎ',workReview:'受注調整'})[t.type]}の結果待ち`),...(s.backlog?[`未完了の仕事 ${money(s.backlog)}分`]:[]),...(receivables(s)?[`未回収 ${money(receivables(s))}`]:[])];return `<section><h2>届いた結果と、残る課題</h2><h3>結果を確認できたこと</h3><ul>${resolved.map(e=>`<li>${esc(e.title)}</li>`).join('')||'<li>採用・調整の結果はまだありません。</li>'}</ul><h3>この先に残っていること</h3><ul>${issues.map(x=>`<li>${esc(x)}</li>`).join('')||'<li>記録上、結果待ちの施策や積み残しはありません。</li>'}</ul></section>`;}
function result(){const records=experiencePatterns(s),chapters=storyChapters(s);app.innerHTML=header()+`<main class="page result">${upgradeNotice()}<section><p class="eyebrow">${esc(s.name)} · ${monthNow()}か月の記録</p><h1 id="scene-title" tabindex="-1">${endingTitle()}</h1>${s.model!==MODEL?'<p class="notice">旧版の記録を閲覧中です。結果は再計算していません。</p>':''}</section><div class="result-stats"><div><span>人数の変化</span><b>${s.initial.staff+1} → ${staff(s)+1}人</b></div><div><span>区切り時点の取引</span><b>${activeClients(s).length}社</b></div><div><span>手元資金</span><b>${money(s.cash)}</b></div></div><section><h2>あなたの会社が、経験したこと</h2>${chapters.length?timeline():reflection(s).map(n=>`<article><h3>${esc(n.title)}</h3><p>${esc(n.text)}</p></article>`).join('')}</section>${remainingIssues()}${lifeReview()}<section class="company-diary result-diary"><div class="diary-heading"><h2>創業からの全日誌</h2><span>全期間 · 新しい順</span></div>${reportHistory()}</section><section><h2>近い経歴と比べてみる</h2>${records.length?records.map(r=>patternCard(s,r)).join(''):'<p>同じ選択と半年後の経過が揃う比較記録がありません。割合や順位は付けません。</p>'}</section><details><summary>資金・人数の推移と会計</summary>${chart()}${chart('staff','一緒に働く人 / 人')}${ledger()}</details><div class="page-actions"><button data-do="new">別の会社の創業条件を見る</button><button data-do="history">全記録を読む</button><button data-do="export">記録を書き出す</button><button data-do="replay">${s.model===MODEL?'同じ境遇・条件で、もう一度':'新版で同じ境遇から始める'}</button></div>${footer()}</main>${s.checkpoint||s.suspended||s.ended==='observed'?dock('continue-life','この会社を続ける','ここまでの記録を残し、次の月から経営を続けます。'):dock('new','別の会社を始める','新しい創業条件の確認画面へ進みます。')}`;}
function reportHistory(){if(s.timelineVersion)return diaryMonths(timelineRecords().reverse()).map(g=>`<section class="diary-month"><h2>${dateAt(g.month)}</h2>${g.records.map(r=>r.html).join('')}</section>`).join('');return s.events.filter(e=>e.q===0).map(eventView).join('')+s.history.map(h=>`<section class="history-quarter"><h3>${period(h.q)} · 決算と出来事</h3><p>納品 ${money(h.revenue)} / 入金 ${money(h.collections)} / 利益 ${money(h.profit)} / 現金 ${money(h.cash)}</p>${s.events.filter(e=>e.q===h.q).map(eventView).join('')}<details><summary>この時点の統計を読み返す</summary>${momentInsight({...s,q:h.q,last:h,batch:[h.q],history:s.history.filter(x=>x.q<=h.q)})}</details></section>`).join('')||timeline(true);}
let modalStack=[],modalReturnFocus=null;
function show(title,body,surface="information"){
 clock.block('modal',true);
 if(modal.open)modalStack.push({nodes:modal.childNodes?[...modal.childNodes]:null,html:modal.innerHTML,surface:modal.dataset?.surface,scroll:modal.scrollTop,focus:document.activeElement});
 else{modalStack=[];modalReturnFocus=document.activeElement;}
 if(modal.dataset)modal.dataset.surface=surface;
 modal.innerHTML=`<div class="modal-head"><h2>${title}</h2><button class="close" data-do="dismiss">${modalStack.length?'前の画面へ戻る':'閉じる ×'}</button></div>${body}`;
 if(!modal.open)modal.showModal();modal.scrollTop=0;modal.querySelector?.('.close')?.focus({preventScroll:true});
}
function dismissModal(){const previous=modalStack.pop();if(previous){if(modal.dataset)modal.dataset.surface=previous.surface||"information";if(previous.nodes)modal.replaceChildren(...previous.nodes);else modal.innerHTML=previous.html;modal.scrollTop=previous.scroll;previous.focus?.focus({preventScroll:true});}else modal.close();}
function modeExplanation(){if(s?.decisionHeld)return '相談を保留中です。時間は停止しています。「相談に戻る」から判断を再開できます。';if(prefs.auto==='manual')return '選ぶまで時間は停止します。確認付きの判断は、結果を読んで「続ける」で再開します。';return '選択予定を予告してから返答し、結果を表示して日常へ戻ります。比較や選択を始めると停止し、自分で決められます。'+(prefs.auto==='safe'?'資金と会社の終了に関わる相談は、あなたが選ぶまで停止します。':'会社の終了に関わる判断も任せます。');}

function explainChain(id){const root=s.events.find(e=>e.id===id);const related=s.events.filter(e=>e.id===id||e.entities.some(entity=>root?.entities.includes(entity))||e.causes.includes(id));show('同じ人物・取引・選択の記録',eventContext(s,related.map(e=>e.id)).map(eventView).join(''));}
function showCohort(){if(s?.life){show('モデル検証と比較条件',evidenceView());return;}if(s?.timelineVersion){show('ゲーム内集計の条件','<p>0.6では判断と時間経過の規則を変更しました。同じ規則で生成した比較データがないため、旧版の集計を表示しません。実調査は創業時の人数・人材確保と育成の課題・開業後の売上傾向を、対象と時点を添えて参考表示します。顧客依存度は対応する実分布を確認できていないため、自社の値のみを表示します。</p>');return;}show('ゲーム内集計の条件',`<span class="source-tag">実際の企業統計ではありません</span><p>${esc(cohort?.method||'対応する生成集計がありません。')}</p><p>仕事量の分布は、同じ創業境遇・同じ経過月数で期末資金が0以上の会社を集計。各期に1社1件で数えます。選択や取引先は一致していません。</p><p>経歴の比較は同じ選択条件を満たした会社の2期後。12社未満では割合を表示しません。割合の丸めで合計が100%にならない場合があります。</p><p>どちらも成功確率・ランキング・選択の因果効果を示しません。</p>${Object.values(PATTERNS).map(p=>`<h3>${p.label}</h3><p>${p.criteria}</p>`).join('')}<p>モデル ${esc(cohort?.model)} / 設定 ${esc(cohort?.dataVersion)}</p>`);}
function data(){show('データと遊び方',`${evidenceView()}<h3>見守り、ときどき決める</h3><p>判断は「自分で決める」「おまかせ・資金と終了は確認」「すべておまかせ」の3つ。おまかせは実行可能な選択肢から均等に抽選し、最適解を探しません。選択予定を表示してから選び、比較や選択を始めると停止します。進行線で自動選択が近づくことを伝えます。「資金と終了は確認」は資金相談・借入・資金危機・廃業・売却・合併の相談で停止。「すべて」は清算など会社の終了も選び得ます。保存・中断は自動では選びません。5年の節目は記録を表示して続行します。</p><ol><li>創業後は自動進行。月ごとに採用・交渉の結果を確認し、3か月ごとに納品・入金と会計を集計します。</li><li>重要な相談では完全に停止。確定しても年月は変わりません。採用・交渉の結果は、その後の時間経過で届きます。</li><li>上部で一時停止・再生・速度変更。詳細・履歴を開くと停止し、閉じると元の再生状態へ戻ります。手動で停止した場合は再生を押すまで進みません。</li></ol><p>別タブ・画面を離れた後と再読込後は一時停止。再生を押すまで再開しません。離席中の追いつき計算はしません。速度は倍率で選び、設定はブラウザに保存。1か月ずつ進める操作もあります。過去ログへスクロールすると停止し、再生するまで再開しません。報告によって速度は変わりません。記録は年月順に残ります。</p><p>1期＝3か月。創業年の1月から始まる相対年月です。ゲームを閉じている間は進行しません。</p><h3>数字は3つに分かれます</h3><ul><li>会社の数値：このプレイの資金、仕事量、人数。実測の推計利用と仮定を組み合わせて計算。</li><li>実調査：公庫の2025年度調査。融資先に限られた参考資料で、創業時の人数を照合し、人材確保・育成や売上傾向は関連する経験の参考として表示します。</li><li>ゲーム内集計：同じモデルで生成した会社。同じ境遇と時期・選択条件で比べます。</li></ul><p><a href="${REAL_START.url}" target="_blank" rel="noopener">日本政策金融公庫の原資料 ↗</a></p><p>開業費用は、現在使える手元資金とは異なるため比較していません。創業人数は参考表示のみ。0.7の年間採用計画では、公庫の年間計画未達割合を推計利用しています。</p><details><summary>会計・保存の仕様</summary><p>納品を売上、給与・固定費・施策・外注・利息を費用に計上。通常は売上の55%を当期、残りを次期に回収。借入元本は利益に含めず、四半通常支払いは四半期、備え・復旧などは月次。前受金は負債として納品時に充当し、保険補填は翌月に入金、復旧費と相殺します。税・減価償却・貸倒などは省略しています。</p><p>モデル・設定・乱数・確認中の画面を保存します。同じ初期条件と選択列で再現できます。</p><p><a href="legacy-v02/">0.2の旧版画面</a> / <a href="legacy/">0.1の旧版画面</a></p></details><button data-do="cohort">ゲーム内集計の条件</button><p><a href="requirements.html">設計と検証範囲</a></p>`);}
const ARCHIVES='company-life-archives-v1';
function archives(){const rows=JSON.parse(localStorage.getItem(ARCHIVES)||'[]');if(!Array.isArray(rows))throw Error('保存一覧を読み込めません');return rows;}
function archiveCompany(){if(!s)return;const rows=archives(),raw=JSON.stringify(s);if(rows.some(a=>a.raw===raw))return;rows.push({id:String(Date.now())+'-'+rows.length,name:s.name,month:monthNow(),raw});localStorage.setItem(ARCHIVES,JSON.stringify(rows));}
function restoreArchive(id){try{const saved=archives().find(a=>a.id===id);if(!saved)return;const restored=prepareTimeline(restore(saved.raw));archiveCompany();localStorage.setItem(KEY,JSON.stringify(restored));clock.pause();s=restored;changeCue=null;quickNotice='';dialogKey='';selected=null;readingPast=false;modal.close();render();focusScene();}catch(err){show('会社を読み込めませんでした',`<p>${esc(err.message)}</p>`);}}
function resumeLatest(){readingPast=false;unread=0;const feed=document.querySelector('#life-feed');if(feed)feed.scrollTop=0;const note=document.querySelector('.diary-latest');if(note)note.hidden=true;clock.play();}
app.addEventListener('change',e=>{const setting=e.target.dataset?.setting;if(setting==='speed'){clock.setSpeed(Number(e.target.value));prefs.speed=clock.speed;savePrefs();}if(setting==='auto'){prefs.auto=['manual','safe','all'].includes(e.target.value)?e.target.value:'manual';savePrefs();clock.restart();render();}});
function focusScene(){window.scrollTo(0,0);(document.querySelector('#scene-title')||document.querySelector('#diary-title'))?.focus({preventScroll:true});}
function progress(operation,{automatic=false}={}){if(busy)return;busy=true;try{const oldState=s,before=s?.pending?.id,prior=s?{cash:s.cash,people:staff(s),clients:activeClients(s).length}:null;s=operation();if(!s.pending)delete s.decisionHeld;if(oldState){changeCue=changedPlaces(oldState,s);quickNotice='';}if(prior)recentDelta={cash:Math.round((s.cash-prior.cash)*100)/100,people:staff(s)-prior.people,clients:activeClients(s).length-prior.clients};if(before!==s?.pending?.id)clock.restart();selected=null;forecast=null;persist();render();}catch(err){clock.pause();show('進行を止めました',`<p>${esc(err.message)}</p>`);}finally{busy=false;}}
function start(){draft||=createEncounter(seed(),null,config);introducing=true;welcome();focusScene();}
function beginStory(){const name=draft.name;const run=()=>{s=prepareTimeline(evolveCompany(startLife(createEncounter(draft.seed,name,draft.config,draft.originId))));s.ui={phase:'observe',month:0};readingPast=false;recentDelta={};changeCue=null;quickNotice='';clock.restart();clock.play();brokenRaw='';selected=null;forecast=null;persist();render();focusScene();};if(brokenRaw){show('元の記録を残して始める',`<p>新しい会社を始めると、この版の保存枠を置き換えます。</p><button data-do="export-broken">元の記録を書き出す</button><button id="confirm-start">新しい会社を始める</button>`);document.querySelector('#confirm-start').onclick=()=>{modal.close();run();};}else run();}
function handle(e){const startMode=e.target.closest('[data-start-mode]');if(startMode){prefs.auto=['manual','safe','all'].includes(startMode.dataset.startMode)?startMode.dataset.startMode:'manual';savePrefs();welcome();return;}const archive=e.target.closest('[data-archive]');if(archive){restoreArchive(archive.dataset.archive);return;}const mode=e.target.closest('[data-auto]');if(mode){prefs.auto=mode.dataset.auto;savePrefs();clock.restart();render();document.querySelectorAll('[data-auto]').forEach(b=>b.setAttribute('aria-pressed',String(b.dataset.auto===prefs.auto)));const explanation=modal.querySelector?.('#mode-explanation');if(explanation)explanation.textContent=modeExplanation();return;}const speed=e.target.closest('[data-speed]');if(speed){clock.setSpeed(Number(speed.dataset.speed));prefs.speed=clock.speed;savePrefs();document.querySelectorAll('[data-speed]').forEach(b=>b.setAttribute('aria-pressed',String(Number(b.dataset.speed)===clock.speed)));return;}if(e.target.closest('summary')&&e.currentTarget===app)clock.block('reading',true);const choice=e.target.closest('[data-choice]');if(choice){if(s?.decisionReceipt||!s?.pending)return;const a=availableDecisionOptions(s).find(a=>a.id===choice.dataset.choice);if(!a)return;if(prefs.auto!=='manual')clock.pause();selected=a.id;if(isLightChoice(s.pending,a)){quickDecision();return;}updateDecisionSelection();return;}const origin=e.target.closest('[data-origin]');if(origin){draft=createEncounter(seed(),document.querySelector('#company')?.value||null,config,origin.dataset.origin);welcome();return;}const event=e.target.closest('[data-event]');if(event){explainChain(event.dataset.event);return;}const help=e.target.closest('[data-help]');if(help){if(modal.open)modal.close();progress(()=>{const n=requestHelp(s,help.dataset.help);delete n.decisionHeld;n.helpReturnUi=s.ui;n.ui={phase:'observe',month:s.ui?.month||0};return n;});return;}const candidate=e.target.closest('[data-candidate]');if(candidate){modal.close();progress(()=>contactCandidate(s,candidate.dataset.candidate));return;}const policy=e.target.closest('[data-policy]');if(policy){modal.close();progress(()=>setPolicy(s,policy.dataset.policy));return;}const action=e.target.closest('[data-do]')?.dataset.do;if(!action)return;
 
 if(action==='hold-decision'){s.decisionHeld=true;persist();render();document.querySelector('.play-toggle')?.focus({preventScroll:true});return;}
 if(action==='reopen-decision'){delete s.decisionHeld;persist();render();return;}
 if(action==='continue-result'){continueResult();return;}
 if(action==='decision-pause'){clock.wanted?clock.pause():clock.play();renderDecision();return;}
 if(action==='cycle-speed'){const speeds=[.125,.25,.5,1,2];clock.setSpeed(speeds[(speeds.indexOf(clock.speed)+1)%speeds.length]);prefs.speed=clock.speed;savePrefs();render();return;}
 if(action==='play-settings'){show('見守り方の設定',`<h3>時間の速さ</h3>${speedControls()}<h3>判断を任せる範囲</h3><div class="setting-buttons">${Object.entries(autoLabels).map(([v,t])=>`<button data-auto="${v}" aria-pressed="${prefs.auto===v}">${t}</button>`).join('')}</div><p id="mode-explanation">${modeExplanation()}</p>`,"settings");return;}
 if(action==='begin-story'){beginStory();return;}if(action==='company'){show('会社のこと',`${upgradeNotice()}${metrics()}${supportPanel()}${parallelWork()}${lifePanel()}<details><summary>会計の内訳</summary>${ledger()}</details><div class="menu-actions"><button data-do="relationships">人と取引</button><button data-do="history">全履歴</button><button data-do="new">別の会社を始める</button><button data-do="saved-companies">保存した会社</button><button data-do="save-pause">保存・中断</button><button data-do="export">記録を書き出す</button><button data-do="data">データと遊び方</button></div>`);return;}if(action==='menu'&&!s){data();return;}if(action==='menu'){show('会社メニュー','<div class="menu-actions"><button data-do="save-pause">保存・中断</button><button data-do="history">履歴</button><button data-do="relationships">人と取引</button><button data-do="data">データと遊び方</button><button data-do="export">記録を書き出す</button></div>');return;}
 if(action==='resume-latest'){resumeLatest();return;}
 if(action==='step-month'){if(s.pending||s.decisionReceipt||s.checkpoint||s.suspended||s.ended||modal.open)return;clock.pause();progress(()=>tickMonth(s));clock.restart();return;}
 if(action==='latest'){readingPast=false;unread=0;render();window.scrollTo(0,0);document.querySelector('#diary-title')?.focus({preventScroll:true});return;}if(action==='summary'){s.ui={...s.ui,summary:true};persist();render();focusScene();return;}if(action==='toggle-play'&&s.suspended){progress(()=>continueLife(s));clock.play();return;}if(action==='toggle-play'&&s.decisionHeld){delete s.decisionHeld;persist();render();return;}if(action==='toggle-play'){if(clock.wanted)clock.pause();else resumeLatest();return;}if(action==='dismiss'){dismissModal();return;}if(action==='data'){data();return;}if(action==='cohort'){showCohort();return;}if(action==='relationships'){relationships();return;}if(action==='start'){start();return;}
 if(action==='reroll'){draft=createEncounter(seed(),null,config);welcome();return;}
 if(action==='decide'&&selected&&!s.decisionReceipt){decide(false);return;}
 if(action==='cancel-help'){const old=s.helpReturnUi;progress(()=>cancelHelp(s));s.ui=old||{phase:'observe'};delete s.helpReturnUi;persist();render();return;}
 if(action==='history'){show('この会社が、歩いてきたこと',`<p>${esc(s.name)} / ${s.q*3}か月 / ${s.decisions.length}回の判断</p>${reportHistory()}`);return;}
 if(action==='export'||action==='export-broken'){exportFile(action==='export'?JSON.stringify(s,null,2):brokenRaw,'company-life-record.json');return;}
 if(action==='save-pause'){clock.pause();persist();show('記録を保存して中断',`<p>${saveError?esc(saveError):'この会社の経過を保存しました。会社は終了していません。閉じた後も、再生を押すまで進みません。'}</p><button data-do="export">記録を書き出す</button>`);return;}
 if(action==='upgrade-company'){progress(()=>evolveCompany(s));return;}
 if(action==='leadership'){modal.close();progress(()=>requestLeadership(s));return;}
 if(action==='strategy'){modal.close();progress(()=>requestStrategy(s));return;}
 if(action==='family-add'){const name=document.querySelector('#family-name')?.value;modal.close();progress(()=>registerFamily(s,name));return;}
 if(action==='family-form'){show('家族の後継候補を登録',`<label for="family-name">候補者の名前</label><input id="family-name" maxlength="24" placeholder="架空の人物名"><p>登録だけで入社や承継は成立しません。1年間の準備を別途進めます。</p><button data-do="family-add">候補者として記録する</button>`);return;}
 if(action==='generations'){show('経営者の時代と会社の経過',generationReview());return;}
 if(action==='close-company'&&s.life){modal.close();progress(()=>requestExit(s));return;}
 if(action==='continue-life'){if(modal.open)modal.close();progress(()=>continueLife(s));clock.play();return;}
 if(action==='upgrade-life'){progress(()=>continueLife(startLife(s,config)));clock.play();return;}
 if(action==='evidence'){show('実測・推計・仮定の境界',evidenceView());return;}
 if(action==='policies'){show('備えと資金繰り — 時間は進みません',policyOptions(s).map(a=>`<article class="relationship-card"><h3>${esc(a.title)}</h3><p>${esc(a.desc)}</p><p>対応条件・費用は仮定です。</p><button data-policy="${a.id}" ${s.pending||s.checkpoint||a.cost>s.cash?'disabled':''}>${a.cost?money(a.cost)+'で':'この時点で'}登録する</button></article>`).join('')||'<p>現在追加できる備えはありません。</p>');return;}
 if(action==='close-company'){show('経営をここで区切る',`<p>ここまでの記録を振り返ります。この会社の進行は再開できなくなります。</p><button data-do="confirm-close">経営を区切って振り返る</button><button data-do="dismiss">戻る</button>`);return;}
 if(action==='confirm-close'){modal.close();clock.block('modal',false);progress(()=>close(s));return;}if(action==='new'){clock.pause();show('今の会社を残して、新しい出会いへ',`<p>「${esc(s.name)}」の${monthNow()}か月の記録と、判断・結果待ちをこのブラウザに保存します。会社は廃業しません。「会社のこと → 保存した会社」から再開できます。</p><p>別の端末にも残す場合は、記録を書き出してください。</p><button data-do="export">記録を書き出す</button><button class="primary" data-do="archive-new">保存して別の会社へ</button><button data-do="dismiss">この会社に戻る</button>`);return;}
 if(action==='archive-new'){try{archiveCompany();}catch(err){show('保存できませんでした',`<p>${esc(err.message)} 現在の会社を残したまま停止しています。記録を書き出してから再度お試しください。</p><button data-do="export">記録を書き出す</button><button data-do="dismiss">戻る</button>`);return;}modal.close();if(decisionModal.open)decisionModal.close();s=null;dialogKey='';dialogState=null;introducing=false;draft=null;readingPast=false;syncClock();welcome();focusScene();return;}
 if(action==='saved-companies'){try{show('保存した会社',archives().map(a=>`<article class="relationship-card"><h3>${esc(a.name)}</h3><p>創業${a.month}か月 · このブラウザに保存</p><button data-archive="${a.id}">この会社を再開する</button></article>`).join('')||'<p>まだ別に保存した会社はありません。</p>');}catch(err){show('保存一覧を読み込めません',`<p>${esc(err.message)}。現在の会社はそのまま残っています。</p>`);}return;}if(action==='replay'){clock.play();progress(()=>prepareTimeline(evolveCompany(startLife(s.encounter?createEncounter(s.seed,s.name,s.config,s.originId):create(s.seed,s.name,s.model===MODEL?s.config:config,s.originId)))));}
}

function ledger(){const l=s.last;const rows=s.q?[[`期首の現金`,money(l.startCash)],['納品した仕事の売上',money(l.revenue)],['給与・報酬・固定費・施策・外注費',`−${money(l.operating)}`],['借入利息',`−${money(l.interest)}`],['当期利益 = 売上 − 費用 − 利息',money(l.profit)],['実際に回収した現金',`＋${money(l.collections)}`],['新規借入（売上に含めない）',`＋${money(l.borrow)}`],['返済元本（費用に含めない）',`−${money(l.repay)}`],['登録時に支払済み（再度引き落とさない）',money(l.prepaid||0)],['期末現金 = 期首 + 回収 + 借入 − 費用 + 支払済み − 利息 − 返済',money(s.history.at(-1)?.cash??s.cash)]]:[];return `<table class="ledger"><tbody>${[...rows,['現在の手元資金（期中の支出・入金を含む）',money(s.cash)],['入金待ちの売掛金',money(receivables(s))],['借入残高',money(s.debt)],['前受金（納品前の負債）',money(s.life?.advanceLiability||0)],['現在の体制での通常費用',`${money(costs(s))} / 四半期`]].map(([a,b])=>`<tr><td>${a}</td><td>${b}</td></tr>`).join('')}</tbody></table>`;}

function chart(metric='cash',label='手元資金 / 万円'){const values=[metric==='cash'?s.initial.cash:metric==='staff'?s.initial.staff+1:0,...s.history.map(h=>metric==='staff'?h.staff+1:h[metric])];const lo=Math.min(0,...values),hi=Math.max(1,...values),x=i=>45+i/Math.max(1,values.length-1)*485,y=v=>135-(v-lo)/(hi-lo)*110;return `<div class="chart-label"><span>${label}</span><span>創業 → ${s.q*3}か月</span></div><svg class="chart" viewBox="0 0 550 160" role="img" aria-label="${label}。創業時${num(values[0])}から現在${num(values.at(-1))}"><line x1="45" y1="25" x2="530" y2="25"/><line x1="45" y1="135" x2="530" y2="135"/><text x="0" y="29">${num(hi)}</text><text x="0" y="139">${num(lo)}</text><polyline points="${values.map((v,i)=>`${x(i)},${y(v)}`).join(' ')}"/>${values.map((v,i)=>`<circle cx="${x(i)}" cy="${y(v)}" r="2.7"><title>${period(i)}: ${num(v)}</title></circle>`).join('')}<text x="45" y="157">創業</text><text x="470" y="157">${s.q*3}か月</text></svg>`;}

function relationships(){show('この会社と、縁のある人たち',`${candidateContacts()}<div class="eyebrow">いま、一緒に働く人</div><div class="people-list">${activeTeam(s).map(p=>`<article><strong>${esc(p.name)}</strong><p>${esc(p.role)}${p.profile?`（${esc(p.profile.label)}）`:""} / ${p.founding?'創業から一緒':`${dateAt(personJoinedMonth(s,p))}に入社`} / 報酬${money(p.salary)}/期</p>${p.profile?`<p>${esc(p.profile.description)}<br>一緒に働いた期間 ${Math.max(0,monthNow()-personJoinedMonth(s,p))}か月 / 仕事量の多かった期間 ${p.overloadPeriods*3}か月 / ${esc(personCondition(p).text)}</p>`:""}</article>`).join('')||'<p>今は、創業者ひとりで会社を回しています。</p>'}</div>${s.people.some(p=>!p.active)?`<div class="eyebrow">別の道へ進んだ仲間</div><div class="people-list">${s.people.filter(p=>!p.active).map(p=>`<article><strong>${esc(p.name)}</strong><p>${p.founding?'創業の日':dateAt(personJoinedMonth(s,p))}から${dateAt(personLeftMonth(s,p))}まで。${esc(p.leftReason)}</p></article>`).join('')}</div>`:''}<div class="eyebrow">取引先との関係</div>${s.clients.map(c=>`<div class="relationship-card"><strong>${esc(c.name)}</strong><span>${c.active?'継続中':'今回の取引は終了'}</span><p>${clientSinceMonth(s,c)===0?'創業時から':`${dateAt(clientSinceMonth(s,c))}から`}のつながり / ${c.active?`基準の仕事量 ${money(clientWork(s,c))}/期`:'継続契約には至らなかった'}${c.renewed?' / 続ける関係を考えた相手':''}</p>${c.sourceEvent?`<button class="causal-link" data-event="${c.sourceEvent}">この関係の、はじまりを見る ↗</button>`:''}</div>`).join('')||'<p>継続顧客は、まだいません。</p>'}${s.contacts.length?`<details><summary>相談した相手、つながらなかった話も見る</summary>${s.contacts.map(c=>`<p><b>${esc(c.name)}</b> / ${({available:'相談が届いている',passed:'今回は見送った',declined:'大口の相談を見送った',trial:'試作を進めた',negotiating:'契約を相談した',won:'契約につながった',lost:'契約に至らなかった'})[c.status]||esc(c.status)}</p>`).join('')}</details>`:''}`);}

function measureJournalHeader(){const height=document.querySelector('.topbar')?.offsetHeight;if(height)document.documentElement?.style.setProperty('--journal-header-offset',`${height+16}px`);}
window.addEventListener('resize',measureJournalHeader);
app.addEventListener('toggle',()=>clock.block('reading',!!app.querySelector('details[open]')),true);
document.addEventListener('visibilitychange',()=>{if(document.hidden){clock.pause();clock.block('hidden',true);}else clock.block('hidden',false);});
window.addEventListener('pagehide',()=>clock.pause());

modal.addEventListener('cancel',e=>{e.preventDefault();dismissModal();});
modal.addEventListener('close',()=>{modalStack=[];modalReturnFocus?.focus({preventScroll:true});modalReturnFocus=null;clock.block('reading',!!app.querySelector('details[open]'));clock.block('modal',false);});
decisionModal.addEventListener('pointerdown',e=>{if(clock.running&&prefs.auto!=='manual'&&e.target.closest?.('.decision-body')){clock.pause();refreshPlayback();}});
decisionModal.addEventListener('keydown',e=>{if(prefs.auto==='manual'||!clock.running)return;if(e.key==='Tab'||(['ArrowUp','ArrowDown','ArrowLeft','ArrowRight','Enter',' '].includes(e.key)&&!e.target.closest?.('[data-do="decision-pause"]'))){clock.pause();refreshPlayback();}});
decisionModal.addEventListener('cancel',e=>e.preventDefault());decisionModal.addEventListener('click',handle);decisionModal.addEventListener('toggle',()=>clock.block('decision-reading',!!decisionModal.querySelector?.('details[open]')),true);decisionModal.addEventListener('close',()=>clock.block('decision-reading',false));
app.addEventListener('click',handle);modal.addEventListener('click',handle);modal.addEventListener('click',e=>{if(e.target===modal)dismissModal();});
try{const r=await Promise.all([fetch('model-data.json'),fetch('cohort.json').catch(()=>null)]);if(!r[0].ok)throw Error('設定を読み込めません');config=await r[0].json();if(r[1]?.ok)cohort=await r[1].json();try{legacy=!!localStorage.getItem('company-life-save-v1');const prior=localStorage.getItem('company-life-save-v2'),raw=localStorage.getItem(KEY);if(!raw&&prior){try{s=reviewRecord(prior);}catch{legacy=true;}}if(raw){try{s=prepareTimeline(restore(raw));}catch(err){brokenRaw=raw;saveError=err.message;}}}catch{saveError='このブラウザでは保存を利用できません。';}clock.block('hidden',!!document.hidden);render();}catch(err){app.innerHTML=`<main class="page"><h1>会社を開けませんでした。</h1><p>${esc(err.message)}</p><button onclick="location.reload()">再読み込み</button></main>`;}

function endingTitle(){return s.suspended?'記録を保存して、中断しています。':s.checkpoint?`${monthNow()/12}年を重ねた。会社の時間は、この先へ。`:({observed:'経営を続けたまま、今回の観測を終えた。',voluntary:'自主廃業を選び、会社を閉じた。',liquidated:'再建を断念し、清算へ進んだ。',succession:'仲間へ会社を託し、経営を退いた。',sold:'独立した会社としての物語を終えた。',merged:'新しい会社へ統合された。','five-years':'創業編の節目。会社の時間は、この先へ。',closed:'ここで経営の区切りを選びました。'})[s.ended]||'支払いをつなげず、経営を終えました。';}
function evidenceCard(key,body){const d=EVIDENCE[key];return `<section class="real-moment"><span class="source-tag">${esc(d.kind)}</span>${body}<details><summary>対象・時点・出典と利用限界</summary><p>${esc(d.population)}</p><p>${esc(d.observed)}</p><p>${esc(d.limit)}</p><a href="${d.url}" target="_blank" rel="noopener">${esc(d.source)} · ${d.page} ↗</a></details></section>`;}
function evidenceView(){return `${successionEvidence()}<h3>実測を、どこで会社の時間に使うか</h3><p>0.8は新規会社と明示移行した記録に適用。旧記録は自動で確率を置き換えません。実測は対象集団の観測値、推計は別期間・別条件への変換、仮定は未測定のゲーム設計です。</p>${evidenceCard('cyber',`<h3>年に1回以上の発生経験：12.2% / 17.1%</h3><p>自己診断70点以上 / 69点以下の小規模企業群。発生企業の「影響なし」は32.2% / 23.0%。発生と影響を別に抽選します。</p><p><b>推計：</b>月率 = 1 − (1 − 年率)^(1/12)。その年の初回経験まで月ごと独立・一定の危険度と仮定。同一年の複数事故は1つの事件経過に集約する簡略化です。低得点群なら月${(monthlyHazard(.171)*100).toFixed(2)}%。初期群は調査内の構成比を移植した架空の条件です。対策の購入効果を証明する数字ではありません。</p>`)}${evidenceCard('hiring','<h3>年間採用計画が未達：31.9%</h3><p><b>推計：</b>募集する1名を12か月以内に迎えられるかに移植。0.8の入社月は別の仮定分布（2・3・4・6・9・12か月）。紹介への切替・追加採用は別集計。計画人数が異なる実集団と、ゲームの小さな会社は同一ではありません。紹介で合意済みの候補者は別で、3か月後の入社予定として扱います。</p>')}${evidenceCard('departures','<h3>年間退職者0人：45.4%</h3><p>個人の離職率へ換算せず参考表示のみ。ゲームの離職・入金遅延・受注の確率は仮定のままです。</p>')}<h3>対応が変えるもの</h3><ul><li>バックアップ：復元方法と停止期間。発生率は変えません。</li><li>保険：対象復旧費の自己負担。事故・停止・流出を消しません。</li><li>前受金：未回収額と手元資金。相手の事故率は変えません。</li><li>採用・外注：能力と費用。従業員の負担が次の相談・離職条件に残ります。</li></ul><p>復旧費・停止月数・保険条件・情報管理整備による参照群変更は仮定です。0.8の承継は準備・在籍・負担・資金条件で確認し、旧65%抽選を使いません。売却・合併の合意率は<b>仮定</b>です。被害ありの内訳（軽微45%・一部40%・全面15%）と流出も仮定。軽微は5%、一部は35%、全面は100%の能力損失として期間に応じて決算へ反映します。資金不足から再建・清算へ進み、独立した倒産抽選は行いません。</p><p><a href="model-data.json">全設定・根拠の分類</a> / <a href="evidence.js">抽選に使う実装</a> / <a href="validation-v08.json">0.8の採用時期・長期試行</a> / <a href="validation.json">0.7の抽選検算</a> / <a href="requirements.html">設計と検証範囲</a></p>`;}
function lifePanel(){if(s.life?.version>=2)return generationPanel();if(!s.life)return '<p class="notice">旧ルールの会社です。5年の振り返りで、履歴を残して0.7へ移行できます。</p>';return `<section class="parallel-work"><h2>備えと、経営の区切り</h2><p>情報管理：${s.life.securityGroup==='high'?'組織的な運用':'属人的な運用'}<br>隔離バックアップ ${s.life.backup?'あり':'なし'} / 保険 ${s.life.insurance?'あり':'なし'}</p>${!s.ended&&!s.checkpoint?`<button data-do="policies" ${s.pending?'disabled':''}>備え・前受金・債権回収を検討</button><button data-do="close-company" ${s.pending||s.life.exitPlan?'disabled':''}>廃業・承継・売却・観測終了を検討</button>`:''}<button data-do="evidence">抽選と判断の根拠を見る</button></section>`;}
function lifeReview(){if(s.life?.version>=2)return generationReview();if(!s.life)return s.ended==='five-years'?'<section><h2>会社を続ける</h2><p>今後に0.7の採用・サイバー・再建の規則を適用します。過去は再計算しません。移行前の記録は書き出して残せます。</p><button data-do="export">移行前の記録を書き出す</button><button data-do="upgrade-life">0.7へ移行して続ける</button></section>':'';const l=s.life;return `<section><h2>会社の継続と、自分の経営</h2><p>会社：${l.companyStatus==='closed'?'終了':'継続'} / 自分の経営：${({active:'継続',retired:'退任',ended:'終了'})[l.managementStatus]}</p>${l.ownerProceeds!==undefined?`<p>売却対価（経営者に帰属）：${money(l.ownerProceeds)}。会社の手元資金には加えていません。価格式は仮定です。</p>`:''}${s.checkpoint||s.suspended||s.ended==='observed'?'<button class="primary" data-do="continue-life">この会社を続ける</button>':''}<h3>今回の経験と、比較できる数字</h3><p>年間採用計画の結果 ${l.recruitHistory.length}件 / 計画未達 ${l.recruitHistory.filter(r=>r.filled<r.planned).length}件。インシデント ${l.incidents.length}件 / 影響なし ${l.incidents.filter(r=>r.noImpact).length}件。これは1社の経歴であり、実統計の年率と直接比べる割合ではありません。</p>${evidenceCard('closure','<h3>休廃業・解散企業の49.1%は直近黒字だった。</h3><p>会社を閉じる理由は赤字だけではありません。この数字を「黒字の会社が廃業する確率」として抽選していません。</p>')}${evidenceCard('survival','<h3>参考集団では、4年間で廃業8.9%、存続89.7%。</h3><p>追跡不能1.4%。調査対象と観測開始が異なるため、あなたの会社の寿命や成功順位には換算しません。</p>')}<button data-do="evidence">実測・推計・仮定を確認する</button></section>`;}
function lifeEventInsight(e){if(!s.life)return '';if(e.topic==='cyber'&&s.life.incidents.some(i=>i.eventId===e.id)){const i=s.life.incidents.find(i=>i.eventId===e.id);return evidenceCard('cyber',`<h3>「起きた」と「被害が残った」は、別のこと。</h3><p>この会社が参照した群の年間発生経験は${i.annual*100}%。発生企業の影響なしは${i.group==='high'?'32.2':'23.0'}%。今回は${i.noImpact?'影響を確認せず':'業務に影響が残り、復旧を判断'}。群の月率への変換は推計です。</p>`);}if(e.topic==='generationReview'&&s.events.find(x=>x.topic==='generationReview')?.id===e.id)return successionEvidence();if(e.topic==='recruitPlan')return evidenceCard('hiring','<h3>採用不足は、候補者の確率ではなく計画の経過。</h3><p>実調査では年間計画未達31.9%。この会社も1年間の実績を集計しました。入社月は集計月とは別です。1名計画への移植は推計で、紹介による合意済み入社とは別です。</p>');return '';}

function upgradeNotice(){return s?.life&&s.life.version<2&&!['sold','liquidated','voluntary'].includes(s.ended)?'<section class="notice"><h2>0.8へ引き継ぐ</h2><p>過去を残して、今後に世代交代・採用時期・被害段階の新規則を適用します。予定済みの入社日は変更しません。</p><button data-do="export">移行前の記録を書き出す</button><button class="primary" data-do="upgrade-company">この会社を0.8へ引き継ぐ</button></section>':'';}
function candidateContacts(){const c=s.life?.savedCandidates||[];return c.length?`<section><h2>連絡先を残した採用候補</h2>${c.map(p=>`<article class="relationship-card"><b>${esc(p.name)}</b><p>${esc(p.profile.label)} · ${p.status==='held'?'回答を保留中':'入社を手配済み'}</p>${p.status==='held'?`<button data-candidate="${p.id}" ${s.pending||s.checkpoint||s.suspended||s.ended?'disabled':''}>改めて連絡する</button>`:''}</article>`).join('')}</section>`:'';}
function generationPanel(){const l=s.life,g=currentLeader(s),blocked=s.pending||s.ended||s.checkpoint||s.suspended;return `<section class="parallel-work"><h2>第${g.number}代 · ${esc(g.name)}</h2><p>${dateAt(g.start)}からの経営。${l.handover?`${esc(l.handover.name)}へ交代準備中。`:''}</p><button data-do="generations">歴代経営者と売上・利益・人数を見る</button>${s.suspended?'<button class="primary" data-do="continue-life">保存した会社を再開する</button>':''}${!s.ended?`<button data-do="leadership" ${blocked||l.handover?'disabled':''}>社員・家族への世代交代を検討</button><button data-do="family-form" ${blocked?'disabled':''}>家族の後継候補を記録</button><button data-do="strategy" ${blocked?'disabled':''}>組織・既存事業・新事業を見直す</button><button data-do="policies" ${blocked?'disabled':''}>備え・前受金・債権回収を検討</button><button data-do="close-company" ${blocked||l.exitPlan?'disabled':''}>廃業・売却・合併を検討</button>`:''}<button data-do="evidence">抽選と比較の根拠を見る</button></section>`;}
function successionEvidence(){const p=SUCCESSION_EVIDENCE.profit;return `<section class="real-moment"><span class="source-tag">承継後の実調査 · 抽選には使用しない</span><h3>交代した会社にも、違う経過がある。</h3>${bars(p.labels,p.values,-1)}<p>当期利益を承継時と比べた回答。経過期間は一定ではなく、売上の増加率でもありません。</p><details><summary>3資料の対象・期間・比較の限界</summary>${Object.values(SUCCESSION_EVIDENCE).map(d=>`<p><b>${esc(d.source)}</b><br>${esc(d.population)}<br>${esc(d.observed)}<br>${esc(d.limit)} <a href="${d.url}" target="_blank" rel="noopener">${esc(d.page)} ↗</a></p>`).join('')}<p>ゲームは四半期決算の税等を省略した利益を記録。実調査の当期利益や自己評価とは同一ではなく、率を合わせるための調整は行いません。</p></details></section>`;}
function generationReview(){const l=s.life;return `<section><h2>会社と、歴代の経営者</h2><p>会社：${l.companyStatus==='closed'?'事業終了':l.companyStatus==='integrated'?'他社・新会社へ統合':'継続'}${s.suspended?' · 保存・中断中（終了ではありません）':''}</p>${s.checkpoint||s.suspended?'<button class="primary" data-do="continue-life">この会社を続ける</button>':''}${l.epilogue?`<h3>引き継がれた事業の後日談</h3><p>${esc(l.epilogue.text)}</p>`:''}${l.generations.map(g=>`<article class="relationship-card"><h3>第${g.number}代 · ${esc(g.name)}</h3><p>${dateAt(g.start)}から${g.end?dateAt(g.end)+'まで':'現在まで'} / 方針：${esc(({growth:'新分野を育てる',maintain:'既存の信頼を守る',focus:'採算を整える',organise:'組織化',stopVenture:'投資の整理'})[g.policy]||g.policy)}</p><p>引継ぎ時：資金${money(g.baseline.cash)}・借入${money(g.baseline.debt)}・${g.baseline.staff}人・顧客${g.baseline.clients.length}社・進行案件${g.baseline.contracts.length}件。履歴と結果待ちは保持。</p><div class="generation-table"><table class="ledger"><thead><tr><th>観測</th><th>売上</th><th>利益</th><th>人数</th></tr></thead><tbody>${[g.baseline,...g.reviews].map((r,i)=>`<tr><td>${i?`${(r.month-g.start)/12}年後`:esc(g.baselineLabel||'引継ぎ時')}<small>直近${r.periodMonths}か月</small></td><td>${money(r.revenue)}</td><td>${money(r.profit)}</td><td>${r.staff}人</td></tr>`).join('')}</tbody></table></div></article>`).join('')}${successionEvidence()}<p>新事業・組織化・取引整理は、費用と日々の受注・納品を通じて結果が生まれます。年数だけの終了や承継時の成長ボーナスはありません。</p><p><a href="validation-v08.json">採用時期・年間実績・長期試行の検証結果</a></p></section>`;}
